using namespace std;
struct P{int x,y;};
long long cr(P a,P b,P c){return 1LL*(b.x-a.x)*(c.y-a.y)-1LL*(b.y-a.y)*(c.x-a.x);}
array<P,4> blk(int m,int s,int t,int e){int n=2*m;auto J=[n](int x){return n-1-x;};P q0{s,e?J(t):t},q1{J(s),e?t:J(t)};return {q0,q1,P{J(q0.y),q0.x},P{J(q1.y),q1.x}};}
int pair_atomic(int m,int sa,int ta,int ea,int sb,int tb,int eb){auto a=blk(m,sa,ta,ea),b=blk(m,sb,tb,eb);array<P,8>p{};array<int,8>o{};for(int i=0;i<4;i++){p[i]=a[i];p[i+4]=b[i];o[i+4]=1;}int z=0;for(int i=0;i<8;i++)for(int j=i+1;j<8;j++)for(int k=j+1;k<8;k++){if(o[i]==o[j]&&o[j]==o[k])continue;z+=cr(p[i],p[j],p[k])==0;}return z;}
int triple_atomic(int m,int a,int ta,int ea,int b,int tb,int eb,int c,int tc,int ec){auto A=blk(m,a,ta,ea),B=blk(m,b,tb,eb),C=blk(m,c,tc,ec);int z=0;for(auto x:A)for(auto y:B)for(auto w:C)z+=cr(x,y,w)==0;return z;}
struct G{int m;size_t six;vector<int8_t>rel;vector<uint8_t>pc,tc;G(int M):m(M),six((size_t)m*m*m*m*m*m),rel((size_t)m*m*m*m),pc((size_t)m*m*m*m*4),tc(six*8){for(int a=0;a<m;a++)for(int ta=0;ta<m;ta++){if(ta==a)continue;for(int b=a+1;b<m;b++)for(int tb=0;tb<m;tb++){if(tb==b||tb==ta)continue;auto id=i4(a,ta,b,tb);for(int ea=0;ea<2;ea++)for(int eb=0;eb<2;eb++)pc[id*4+ea*2+eb]=pair_atomic(m,a,ta,ea,b,tb,eb);bool be=pc[id*4]>0,bu=pc[id*4+1]>0;rel[id]=be&&bu?3:be?2:bu?1:0;}}for(int a=0;a<m;a++)for(int ta=0;ta<m;ta++){if(ta==a)continue;for(int b=a+1;b<m;b++)for(int tb=0;tb<m;tb++){if(tb==b||tb==ta)continue;for(int c=b+1;c<m;c++)for(int u=0;u<m;u++){if(u==c||u==ta||u==tb)continue;auto id=i6(a,ta,b,tb,c,u);for(int e=0;e<8;e++)tc[id*8+e]=triple_atomic(m,a,ta,e&1,b,tb,(e>>1)&1,c,u,(e>>2)&1);}}}}
 size_t i4(int a,int ta,int b,int tb)const{return ((size_t(a)*m+ta)*m+b)*m+tb;}size_t i6(int a,int ta,int b,int tb,int c,int u)const{return (((((size_t(a)*m+ta)*m+b)*m+tb)*m+c)*m+u);}int relation(int a,int ta,int b,int tb)const{return rel[i4(a,ta,b,tb)];}int pairc(int a,int ta,int ea,int b,int tb,int eb)const{return pc[i4(a,ta,b,tb)*4+ea*2+eb];}int triplec(int a,int ta,int ea,int b,int tb,int eb,int c,int u,int ec)const{return tc[i6(a,ta,b,tb,c,u)*8+ea+2*eb+4*ec];}};
uint64_t enc(const array<uint8_t,9>&r,int m){uint64_t x=0;for(int i=0;i<m;i++)x=(x<<4)|r[i];return x;}
array<uint8_t,9> sw(const array<uint8_t,9>&r,int m,array<int,3>s){array<int,3>c{};int f=0,u=min({s[0],s[1],s[2]});for(int k=0;k<m;k++){if(u==s[0]||u==s[1]||u==s[2])c[f++]=u;u=r[u];}auto o=r;o[c[0]]=r[c[1]];o[c[1]]=r[c[2]];o[c[2]]=r[c[0]];return o;}
struct R{int m=0;long long clean=0,valid=0,unresolved=0;map<int,long long>minMacro,maxMacro,hybrid,sourceLambda;int maxHybrid=0;};
R run(int m){G g(m);int O=1<<m;vector<array<uint8_t,9>>cy;vector<int>tail(m-1);iota(tail.begin(),tail.end(),1);do{array<uint8_t,9>ord{},r{};ord[0]=0;for(int i=1;i<m;i++)ord[i]=tail[i-1];for(int i=0;i<m;i++)r[ord[i]]=ord[(i+1)%m];cy.push_back(r);}while(next_permutation(tail.begin(),tail.end()));unordered_map<uint64_t,int>ix;ix.reserve(cy.size()*2);for(int i=0;i<(int)cy.size();i++)ix[enc(cy[i],m)]=i;vector<array<int,3>>tr;for(int a=0;a<m;a++)for(int b=a+1;b<m;b++)for(int c=b+1;c<m;c++)tr.push_back({a,b,c});int K=tr.size();vector<vector<int>>nei(cy.size(),vector<int>(K));for(int i=0;i<(int)cy.size();i++)for(int t=0;t<K;t++)nei[i][t]=ix.at(enc(sw(cy[i],m,tr[t]),m));vector<uint64_t>meetLo(K),meetHi(K);for(int t=0;t<K;t++)for(int s=0;s<K;s++){bool hit=false;for(int x:tr[t])for(int y:tr[s])hit|=x==y;if(hit){if(s<64)meetLo[t]|=1ULL<<s;else meetHi[t]|=1ULL<<(s-64);}}
 size_t N=(size_t)cy.size()*O;vector<int8_t>lambda(cy.size(),-1);vector<uint8_t>optimal(N);vector<int>off(cy.size()+1);vector<uint16_t>oris,atom;vector<uint64_t>flo,fhi;oris.reserve(m==9?7000000:500000);atom.reserve(oris.capacity());flo.reserve(oris.capacity());fhi.reserve(oris.capacity());long long valid=0;
 for(int ci=0;ci<(int)cy.size();ci++){off[ci]=oris.size();vector<array<int,3>>es;bool safe=true;for(int a=0;a<m&&safe;a++)for(int b=a+1;b<m;b++){int v=g.relation(a,cy[ci][a],b,cy[ci][b]);if(v==3){safe=false;break;}if(v)es.push_back({a,b,v==1?0:1});}if(!safe)continue;vector<uint8_t>bad(O);int best=127;for(int e=0;e<O;e++){int q=0;for(auto z:es)q+=((((e>>z[0])&1)^((e>>z[1])&1))!=z[2]);bad[e]=q;best=min(best,q);}lambda[ci]=best;for(int e=0;e<O;e++)if(bad[e]==best)optimal[(size_t)ci*O+e]=1;if(best)continue;for(int e=0;e<O;e++)if(!bad[e]){uint64_t lo=0,hi=0;int at=0;for(int ti=0;ti<K;ti++){auto T=tr[ti];int q=g.triplec(T[0],cy[ci][T[0]],(e>>T[0])&1,T[1],cy[ci][T[1]],(e>>T[1])&1,T[2],cy[ci][T[2]],(e>>T[2])&1);at+=q;if(q){if(ti<64)lo|=1ULL<<ti;else hi|=1ULL<<(ti-64);}}oris.push_back(e);atom.push_back(at);flo.push_back(lo);fhi.push_back(hi);valid+=!(lo|hi);}}
 off[cy.size()]=oris.size();vector<int8_t>dist(oris.size(),-1),cmin(cy.size(),-1);deque<int>q;for(int ci=0;ci<(int)cy.size();ci++)for(int id=off[ci];id<off[ci+1];id++)if(!(flo[id]|fhi[id])){dist[id]=0;if(cmin[ci]<0){cmin[ci]=0;q.push_back(ci);}}while(!q.empty()){int eta=q.front();q.pop_front();int nd=cmin[eta]+1;for(int t=0;t<K;t++){int rho=nei[eta][t];bool any=false;for(int id=off[rho];id<off[rho+1];id++)if(dist[id]<0&&((flo[id]&meetLo[t])||(fhi[id]&meetHi[t]))){dist[id]=nd;any=true;}if(any&&cmin[rho]<0){cmin[rho]=nd;q.push_back(rho);}}}
 vector<int16_t>minZ(N,-1);vector<int8_t>minM(N,-1),maxM(N,-1),hyb(N,-1);for(int ci=0;ci<(int)cy.size();ci++)for(int id=off[ci];id<off[ci+1];id++){int e=oris[id];size_t s=(size_t)ci*O+e;minZ[s]=atom[id];minM[s]=maxM[s]=hyb[s]=dist[id];}
 auto exactZ=[&](int ci,int e){int z=0;for(int a=0;a<m;a++)for(int b=a+1;b<m;b++)z+=g.pairc(a,cy[ci][a],(e>>a)&1,b,cy[ci][b],(e>>b)&1);for(int a=0;a<m;a++)for(int b=a+1;b<m;b++)for(int c=b+1;c<m;c++)z+=g.triplec(a,cy[ci][a],(e>>a)&1,b,cy[ci][b],(e>>b)&1,c,cy[ci][c],(e>>c)&1);return z;};int maxL=*max_element(lambda.begin(),lambda.end());for(int l=1;l<=maxL;l++)for(int ci=0;ci<(int)cy.size();ci++)if(lambda[ci]==l)for(int e=0;e<O;e++)if(optimal[(size_t)ci*O+e]){int z=exactZ(ci,e),mn=z,mi=99,ma=-1,h=99;bool found=false;for(int t=0;t<K;t++){int eta=nei[ci][t];if(lambda[eta]<0||lambda[eta]>=l||!optimal[(size_t)eta*O+e])continue;size_t u=(size_t)eta*O+e;if(minZ[u]<0)continue;found=true;mn=min<int>(mn,minZ[u]);mi=min<int>(mi,minM[u]);ma=max<int>(ma,maxM[u]);h=min<int>(h,1+hyb[u]);}if(!found){cerr<<"no target-optimal descent m="<<m<<" l="<<l<<"\n";exit(2);}size_t s=(size_t)ci*O+e;minZ[s]=mn;minM[s]=mi;maxM[s]=ma;hyb[s]=h;}
 R out;out.m=m;out.clean=oris.size();out.valid=valid;for(int ci=0;ci<(int)cy.size();ci++)if(lambda[ci]>0)for(int e=0;e<O;e++)if(optimal[(size_t)ci*O+e]){size_t s=(size_t)ci*O+e;int z=exactZ(ci,e);if(minZ[s]<z)continue;out.unresolved++;out.minMacro[minM[s]]++;out.maxMacro[maxM[s]]++;out.hybrid[hyb[s]]++;out.sourceLambda[lambda[ci]]++;out.maxHybrid=max(out.maxHybrid,(int)hyb[s]);}return out;}
void pm(const map<int,long long>&x){cout<<"{";bool f=1;for(auto [k,v]:x){if(!f)cout<<",";f=0;cout<<"\""<<k<<"\":"<<v;}cout<<"}";}
int main(){vector<R>rs;for(int m=8;m<=9;m++)rs.push_back(run(m));bool ok=rs[0].clean==404080&&rs[0].valid==28&&rs[0].unresolved==4186&&rs[0].minMacro==map<int,long long>{{1,3020},{2,1166}}&&rs[0].maxMacro==map<int,long long>{{2,1068},{3,3118}}&&rs[0].hybrid==map<int,long long>{{2,3014},{3,1172}}&&rs[0].sourceLambda==map<int,long long>{{1,4170},{2,16}}&&rs[0].maxHybrid==3&&rs[1].clean==6727728&&rs[1].valid==8&&rs[1].unresolved==25894&&rs[1].minMacro==map<int,long long>{{1,3816},{2,19226},{3,2852}}&&rs[1].maxMacro==map<int,long long>{{2,146},{3,10680},{4,15068}}&&rs[1].hybrid==map<int,long long>{{2,3792},{3,19250},{4,2852}}&&rs[1].sourceLambda==map<int,long long>{{1,25862},{2,32}}&&rs[1].maxHybrid==4;if(!ok){cerr<<"base mismatch\n";return 3;}cout<<"{\n  \"cases\":[\n";for(int i=0;i<2;i++){auto&r=rs[i];cout<<"    {\"m\":"<<r.m<<",\"clean_signed_states\":"<<r.clean<<",\"valid_states\":"<<r.valid<<",\"failed_strict_cancellation_sources\":"<<r.unresolved<<",\"minimum_terminal_macro_distance_distribution\":";pm(r.minMacro);cout<<",\"maximum_terminal_macro_distance_distribution\":";pm(r.maxMacro);cout<<",\"minimum_hybrid_length_distribution\":";pm(r.hybrid);cout<<",\"source_frustration_distribution\":";pm(r.sourceLambda);cout<<",\"maximum_minimum_hybrid_length\":"<<r.maxHybrid<<"}"<<(i?"":",")<<"\n";}cout<<"  ],\n  \"strict_repair_then_clean_macro_bridge_verified\":true,\n  \"asymptotic_hybrid_repair_proved\":false\n}\n";}
